    /**
     * or an include rule. include all rules from the included state
     */
    var include: String?
}

typealias IMonarchLanguageRule = IShortMonarchLanguageRule1OrD8255792Union

/**
 * An action is either an array of actions...
 * ... or a case statement with guards...
 * ... or a basic action with a token value.
 */
typealias IShortMonarchLanguageAction = String

external interface IExpandedMonarchLanguageAction {
    /**
     * array of actions for each parenthesized match group
     */
    var group: Array<IMonarchLanguageAction>?
    /**
     * map from string to ILanguageAction
     */
    var cases: JsAny?
    /**
     * token class (ie. css class) (or "@brackets" or "@rematch")
     */
    var token: String?
    /**
     * the next state to push, or "@push", "@pop", "@popall"
     */
    var next: String?
    /**
     * switch to this state
     */
    var switchTo: String?
    /**
     * go back n characters in the stream
     */
    var goBack: Double?
    /**
     * @open or @close
     */
    var bracket: String?
    /**
     * switch to embedded language (using the mimetype) or get out using "@pop"
     */
    var nextEmbedded: String?
    /**
     * log a message to the browser console window
     */
